CASE
    WHEN (CURRENT_USER = 'app_staff'::name) THEN (organization_id = app.current_org_id())
    WHEN (CURRENT_USER = 'app_platform_settings'::name) THEN (organization_id IS NULL)
    ELSE false
END) WITH CHECK (
CASE
    WHEN (CURRENT_USER = 'app_staff'::name) THEN (organization_id = app.current_org_id())
    WHEN (CURRENT_USER = 'app_platform_settings'::name) THEN (organization_id IS NULL)
    ELSE false
END);


